//! Timetable helpers for the island ferry.

/// Convert `HH:MM` text to minutes after midnight, or `None` if it is malformed or out of range.
///
/// # Examples
///
/// ```
/// use ferry::parse_time;
/// assert_eq!(parse_time("07:45"), Some(465));
/// assert_eq!(parse_time("24:00"), None);
/// assert_eq!(parse_time("7.45"), None);
/// ```
pub fn parse_time(text: &str) -> Option<u32> {
    let (h, m) = text.split_once(':')?;
    let (h, m): (u32, u32) = (h.parse().ok()?, m.parse().ok()?);
    if h > 23 || m > 59 {
        return None;
    }
    Some(h * 60 + m)
}

/// Convert minutes after midnight to `HH:MM`, wrapping past midnight.
///
/// # Examples
///
/// ```
/// use ferry::format_time;
/// assert_eq!(format_time(465), "07:45");
/// assert_eq!(format_time(1500), "01:00");
/// ```
pub fn format_time(minutes: u32) -> String {
    let m = minutes % 1440;
    format!("{:02}:{:02}", m / 60, m % 60)
}

/// Find the next sailing at or after `now`; tomorrow's first sailing (plus 1440 minutes) if none is left, `None` without sailings.
///
/// # Examples
///
/// ```
/// use ferry::next_departure;
/// assert_eq!(next_departure(&[420, 600, 900], 500), Some(600));
/// assert_eq!(next_departure(&[420, 600], 700), Some(1860));
/// assert_eq!(next_departure(&[], 10), None);
/// ```
pub fn next_departure(times: &[u32], now: u32) -> Option<u32> {
    let mut sorted = times.to_vec();
    sorted.sort_unstable();
    sorted.iter().copied().find(|&t| t >= now).or_else(|| sorted.first().map(|&t| t + 1440))
}

/// Minutes two `(start, end)` windows share; 0 if they are disjoint.
///
/// # Examples
///
/// ```
/// use ferry::overlap;
/// assert_eq!(overlap((60, 120), (90, 200)), 30);
/// assert_eq!(overlap((0, 10), (20, 30)), 0);
/// ```
pub fn overlap(a: (u32, u32), b: (u32, u32)) -> u32 {
    let start = a.0.max(b.0);
    let end = a.1.min(b.1);
    end.saturating_sub(start)
}

