//! Stock keeping for a community seed bank.

use std::collections::HashMap;

/// Split a SKU such as `VEG-0042` into its prefix and number.
///
/// # Errors
///
/// Returns an error if the prefix is unknown or the number is not a number.
///
/// # Examples
///
/// ```
/// use seedbank::parse_sku;
/// assert_eq!(parse_sku("VEG-0042"), Ok(("VEG".to_string(), 42)));
/// assert!(parse_sku("XYZ-1").is_err());
/// ```
pub fn parse_sku(code: &str) -> Result<(String, u32), String> {
    let (prefix, rest) = code.split_once('-').ok_or_else(|| format!("bad sku: {}", code))?;
    if !["VEG", "HRB", "FLW"].contains(&prefix) {
        return Err(format!("bad sku: {}", code));
    }
    let n: u32 = rest.parse().map_err(|_| format!("bad sku: {}", code))?;
    Ok((prefix.to_string(), n))
}

/// Add packets of a SKU to the stock and return the new count.
///
/// # Errors
///
/// Returns an error if the quantity is zero or the SKU is malformed.
///
/// # Examples
///
/// ```
/// use seedbank::add_lot;
/// use std::collections::HashMap;
/// let mut stock = HashMap::new();
/// assert_eq!(add_lot(&mut stock, "VEG-1", 3), Ok(3));
/// assert_eq!(add_lot(&mut stock, "VEG-1", 2), Ok(5));
/// assert!(add_lot(&mut stock, "VEG-1", 0).is_err());
/// ```
pub fn add_lot(stock: &mut HashMap<String, u32>, sku: &str, qty: u32) -> Result<u32, String> {
    if qty == 0 {
        return Err("quantity must be positive".to_string());
    }
    parse_sku(sku)?;
    let entry = stock.entry(sku.to_string()).or_insert(0);
    *entry += qty;
    Ok(*entry)
}

/// List, in alphabetical order, the SKUs with fewer packets than the threshold.
///
/// # Examples
///
/// ```
/// use seedbank::low_stock;
/// use std::collections::HashMap;
/// let mut stock = HashMap::new();
/// stock.insert("VEG-1".to_string(), 2);
/// stock.insert("HRB-4".to_string(), 9);
/// assert_eq!(low_stock(&stock, 5), vec!["VEG-1".to_string()]);
/// ```
pub fn low_stock(stock: &HashMap<String, u32>, threshold: u32) -> Vec<String> {
    let mut out: Vec<String> = stock.iter().filter(|(_, &q)| q < threshold).map(|(k, _)| k.clone()).collect();
    out.sort();
    out
}

/// Format the text printed on a packet label.
///
/// # Errors
///
/// Returns an error if the SKU is malformed.
///
/// # Examples
///
/// ```
/// use seedbank::format_label;
/// assert_eq!(format_label("VEG-42", 3).unwrap(), "VEG #0042 x3");
/// assert!(format_label("nope", 1).is_err());
