//! Unit conversions and binning for the tide laboratory.

/// Convert a length to metres.
///
/// # Errors
///
/// Returns an error if the unit is not `m`, `cm` or `ft`.
///
/// # Examples
///
/// ```
/// use tidelab::to_metres;
/// assert_eq!(to_metres(250.0, "cm"), Ok(2.5));
/// assert_eq!(to_metres(2.0, "m"), Ok(2.0));
/// assert!(to_metres(1.0, "yd").is_err());
/// ```
pub fn to_metres(value: f64, unit: &str) -> Result<f64, String> {
    match unit {
        "m" => Ok(value),
        "cm" => Ok(value / 100.0),
        "ft" => Ok((value / 3.28084 * 10000.0).round() / 10000.0),
        _ => Err(format!("unknown unit: {}", unit)),
    }
}

/// Limit a value to the closed range `[low, high]`.
///
/// # Examples
///
/// ```
/// use tidelab::clamp;
/// assert_eq!(clamp(5, 0, 3), 3);
/// assert_eq!(clamp(-2, 0, 3), 0);
/// assert_eq!(clamp(2, 0, 3), 2);
/// ```
pub fn clamp(value: i32, low: i32, high: i32) -> i32 {
    value.max(low).min(high)
}

/// Count values per bucket; the result has one more entry than there are edges, and a value equal to an edge goes to the upper bucket.
///
/// # Examples
///
/// ```
/// use tidelab::bucketize;
/// assert_eq!(bucketize(&[1, 5, 9, 10, 25], &[5, 10]), vec![1, 2, 2]);
/// assert_eq!(bucketize(&[], &[1]), vec![0, 0]);
/// ```
pub fn bucketize(values: &[i32], edges: &[i32]) -> Vec<usize> {
    let mut counts = vec![0; edges.len() + 1];
    for &v in values {
        let i = edges.iter().take_while(|&&e| v >= e).count();
        counts[i] += 1;
    }
    counts
}

